{"label":"Generate errors.json","command":"cd /workspace/prompt-paired-012-final-jsonl-errors; md5sum scratch/log.jsonl > /tmp/before.md5; python3 - <<'EOF'
import json
codes=[]; invalid=[]
with open('scratch/log.jsonl','rb') as f:
    raw=f.read().decode('utf-8')
for i,line in enumerate(raw.split('\n'),1):
    s=line.strip()
    if not s: continue
    try:
        obj=json.loads(s)
    except Exception:
        invalid.append(i); continue
    if isinstance(obj,dict) and obj.get('level')=='error' and 'code' in obj:
        codes.append(obj['code'])
out={"codes":codes,"invalid_lines":invalid}
with open('scratch/errors.json','w',encoding='utf-8') as f:
    json.dump(out,f,ensure_ascii=False,indent=2); f.write('\n')
print(out)
EOF
md5sum -c /tmp/before.md5; cat scratch/errors.json"}

